# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="DejaVu Sans, Arial">\n  <rect width="700" height="245" rx="10" fill="#FAFCFF" stroke="#1E3A8A" stroke-width="1.5"/>\n  <rect x="12" y="10" width="676" height="28" rx="6" fill="#1E3A8A"/>\n  <text x="350" y="29" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#FFFFFF">EDEBİYAT ATÖLYESİ: "KARAKTERİMİN YOLCULUĞU" SUNUM SÜRECİ (TDE3.1 &amp; TDE3.2)</text>\n\n  <rect x="18" y="48" width="158" height="108" rx="8" fill="#EFF6FF" stroke="#3B82F6" stroke-width="1.3"/>\n  <text x="97" y="66" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1D4ED8">1. SEÇİM VE ANALİZ</text>\n  <text x="26" y="84" font-size="9.2" fill="#1E293B">• Hikâyeden karakter seç</text>\n  <text x="26" y="100" font-size="9.2" fill="#1E293B">• Fiziksel özellikleri</text>\n  <text x="26" y="116" font-size="9.2" fill="#1E293B">• Ruhsal/psikolojik yapı</text>\n  <text x="26" y="132" font-size="9.2" fill="#1E293B">• Sahip olduğu değerler</text>\n  <text x="26" y="146" font-size="8.8" fill="#1D4ED8">(İhtiyar, Anton, İsmail Hakkı)</text>\n\n  <rect x="186" y="48" width="158" height="108" rx="8" fill="#ECFDF5" stroke="#10B981" stroke-width="1.3"/>\n  <text x="265" y="66" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#047857">2. KARŞILAŞTIRMA</text>\n  <text x="194" y="84" font-size="9.2" fill="#1E293B">• Günlük yaşamdan veya</text>\n  <text x="194" y="98" font-size="9.2" fill="#1E293B">  sanattan bir kişi belirle</text>\n  <text x="194" y="114" font-size="9.2" fill="#1E293B">• Ortak/benzer yönler</text>\n  <text x="194" y="130" font-size="9.2" fill="#1E293B">• Ayrılan/farklı yönler</text>\n  <text x="194" y="146" font-size="8.8" fill="#047857">(Ön bilgilerle bağ kurma)</text>\n\n  <rect x="354" y="48" width="158" height="108" rx="8" fill="#FFFBEB" stroke="#F59E0B" stroke-width="1.3"/>\n  <text x="433" y="66" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#B45309">3. YENİDEN KURGU</text>\n  <text x="362" y="84" font-size="9.2" fill="#1E293B">• Karakteri özgünleştir</text>\n  <text x="362" y="100" font-size="9.2" fill="#1E293B">• Millî-manevi değer kat</text>\n  <text x="362" y="116" font-size="9.2" fill="#1E293B">• Betimleme ve benzetme</text>\n  <text x="362" y="132" font-size="9.2" fill="#1E293B">• Açık ve örtük iletiler</text>\n  <text x="362" y="146" font-size="8.8" fill="#B45309">(Giriş - Gelişme - Sonuç)</text>\n\n  <rect x="522" y="48" width="160" height="108" rx="8" fill="#FDF2F8" stroke="#EC4899" stroke-width="1.3"/>\n  <text x="602" y="66" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#BE185D">4. SUNUM VE DÖNÜT</text>\n  <text x="530" y="84" font-size="9.2" fill="#1E293B">• Kişi kartı ve görseller</text>\n  <text x="530" y="100" font-size="9.2" fill="#1E293B">• Diksiyon ve beden dili</text>\n  <text x="530" y="116" font-size="9.2" fill="#1E293B">• Zaman yönetimi</text>\n  <text x="530" y="132" font-size="9.2" fill="#1E293B">• Öz, akran ve öğretmen</text>\n  <text x="530" y="146" font-size="8.8" fill="#BE185D">  değerlendirmesi (TDE3.4)</text>\n\n  <rect x="18" y="166" width="664" height="66" rx="8" fill="#EEF2FF" stroke="#6366F1" stroke-width="1.3"/>\n  <text x="350" y="184" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#3730A3">DİLİN KULLANIM ALANLARI (TDE3.2.4) VE KONUŞMA YÖNETİMİ (TDE3.1)</text>\n  <text x="30" y="202" font-size="9.5" fill="#1E293B">• Konuşma amacı, süre, hedef kitle ve strateji belirlenir; dilin kullanım alanı (özel, mesleki, kamusal, eğitim) seçilir.</text>\n  <text x="30" y="218" font-size="9.5" fill="#1E293B">• Hazırlıklı konuşmada önceden kaynak taranıp bilgi toplanır; hazırlıksız konuşmada kısa anahtar notlar alınır.</text>\n</svg>', '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="DejaVu Sans, Arial">\n  <rect width="700" height="240" rx="10" fill="#FAFCFF" stroke="#065F46" stroke-width="1.5"/>\n  <rect x="12" y="10" width="676" height="28" rx="6" fill="#065F46"/>\n  <text x="350" y="29" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#FFFFFF">SÖZLÜ SUNUM DEĞERLENDİRME ÖLÇÜTLERİ TABLOSU</text>\n\n  <rect x="18" y="46" width="322" height="86" rx="7" fill="#ECFDF5" stroke="#10B981" stroke-width="1.3"/>\n  <text x="179" y="64" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#047857">PLANLAMA VE İÇERİK KURGUSU</text>\n  <text x="30" y="82" font-size="9.5" fill="#1E293B">• Etkili giriş, gelişme ve sonuç bütünlüğü</text>\n  <text x="30" y="98" font-size="9.5" fill="#1E293B">• Fiziksel ve ruhsal özelliklerde tutarlılık</text>\n  <text x="30" y="114" font-size="9.5" fill="#1E293B">• Karşılaştırma, betimleme, benzetme</text>\n  <text x="30" y="128" font-size="9.5" fill="#047857">• Açık/örtük iletiler ve millî-manevi değerler</text>\n\n  <rect x="360" y="46" width="322" height="86" rx="7" fill="#EFF6FF" stroke="#3B82F6" stroke-width="1.3"/>\n  <text x="521" y="64" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#1D4ED8">SÖZ VARLIĞI VE DİL BİLGİSİ</text>\n  <text x="372" y="82" font-size="9.5" fill="#1E293B">• Bağlama ve hedef kitleye uygun sözcükler</text>\n  <text x="372" y="98" font-size="9.5" fill="#1E293B">• Yabancı kelimeler yerine Türkçe karşılıklar</text>\n  <text x="372" y="114" font-size="9.5" fill="#1E293B">• Deyim, atasözü ve terimlerin doğru kullanımı</text>\n  <text x="372" y="128" font-size="9.5" fill="#1D4ED8">• Dil bilgisi ve bağdaşıklık kurallarına uyum</text>\n\n  <rect x="18" y="142" width="322" height="86" rx="7" fill="#FFFBEB" stroke="#F59E0B" stroke-width="1.3"/>\n  <text x="179" y="160" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#B45309">AKICILIK, SES VE DİKSİYON</text>\n  <text x="30" y="178" font-size="9.5" fill="#1E293B">• İşitilebilir, doğal ses tonu ve konuşma hızı</text>\n  <text x="30" y="194" font-size="9.5" fill="#1E293B">• Doğru telaffuz, vurgu ve tonlama</text>\n  <text x="30" y="210" font-size="9.5" fill="#1E293B">• "Iıı, eee, hmmm" tekrarlarından kaçınma</text>\n  <text x="30" y="224" font-size="9.5" fill="#B45309">• Tekdüze (monoton) olmayan canlı üslup</text>\n\n  <rect x="360" y="142" width="322" height="86" rx="7" fill="#FDF2F8" stroke="#EC4899" stroke-width="1.3"/>\n  <text x="521" y="160" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#BE185D">BEDEN DİLİ, İŞ BİRLİĞİ VE ZAMAN</text>\n  <text x="372" y="178" font-size="9.5" fill="#1E293B">• Etkili jest (el-kol) ve mimik (yüz) kullanımı</text>\n  <text x="372" y="194" font-size="9.5" fill="#1E293B">• Dinleyicilerle doğrudan göz teması kurma</text>\n  <text x="372" y="210" font-size="9.5" fill="#1E293B">• Takım içi görev ve sorumluluk paylaşımı</text>\n  <text x="372" y="224" font-size="9.5" fill="#BE185D">• Verilen süreyi verimli kullanma (Zaman)</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="DejaVu Sans, Arial">\n  <rect width="700" height="255" rx="10" fill="#FAFCFF" stroke="#4C1D95" stroke-width="1.5"/>\n  <rect x="12" y="10" width="676" height="28" rx="6" fill="#4C1D95"/>\n  <text x="350" y="29" text-anchor="middle" font-size="13" font-weight="bold" fill="#FFFFFF">KONULARINA (İÇERİKLERİNE) GÖRE ŞİİR TÜRLERİ</text>\n\n  <rect x="18" y="46" width="212" height="94" rx="7" fill="#FDF2F8" stroke="#EC4899" stroke-width="1.3"/>\n  <text x="124" y="63" text-anchor="middle" font-size="11" font-weight="bold" fill="#BE185D">1. LİRİK ŞİİR</text>\n  <text x="28" y="80" font-size="9.5" fill="#1E293B">• Aşk, özlem, ayrılık, hüzün</text>\n  <text x="28" y="96" font-size="9.5" fill="#1E293B">• Coşkulu ve içten söyleyiş</text>\n  <text x="28" y="112" font-size="9.5" fill="#1E293B">• Örnek: Mihriban (Karakoç),</text>\n  <text x="28" y="128" font-size="9.5" fill="#BE185D">  Karasevda, Veda şiirleri</text>\n\n  <rect x="244" y="46" width="212" height="94" rx="7" fill="#ECFDF5" stroke="#10B981" stroke-width="1.3"/>\n  <text x="350" y="63" text-anchor="middle" font-size="11" font-weight="bold" fill="#047857">2. PASTORAL ŞİİR</text>\n  <text x="254" y="80" font-size="9.5" fill="#1E293B">• Doğa, yayla, dağ, orman</text>\n  <text x="254" y="96" font-size="9.5" fill="#1E293B">• Köy ve çoban yaşamı</text>\n  <text x="254" y="112" font-size="9.5" fill="#1E293B">• Örnek: Bingöl Çobanları,</text>\n  <text x="254" y="128" font-size="9.5" fill="#047857">  Yayla Dumanı</text>\n\n  <rect x="470" y="46" width="212" height="94" rx="7" fill="#EFF6FF" stroke="#3B82F6" stroke-width="1.3"/>\n  <text x="576" y="63" text-anchor="middle" font-size="11" font-weight="bold" fill="#1D4ED8">3. DİDAKTİK ŞİİR</text>\n  <text x="480" y="80" font-size="9.5" fill="#1E293B">• Öğüt, bilgi ve ahlaki ders</text>\n  <text x="480" y="96" font-size="9.5" fill="#1E293B">• Öğretici ve düşündürücü</text>\n  <text x="480" y="112" font-size="9.5" fill="#1E293B">• Örnek: Nasihat koşmaları,</text>\n  <text x="480" y="128" font-size="9.5" fill="#1D4ED8">  fabl ve manzum hikâyeler</text>\n\n  <rect x="18" y="150" width="322" height="94" rx="7" fill="#FEF2F2" stroke="#EF4444" stroke-width="1.3"/>\n  <text x="179" y="167" text-anchor="middle" font-size="11" font-weight="bold" fill="#B91C1C">4. EPİK (DESTANSI) ŞİİR</text>\n  <text x="30" y="185" font-size="9.5" fill="#1E293B">• Konusu: Savaş, kahramanlık, yiğitlik ve vatan sevgisi</text>\n  <text x="30" y="201" font-size="9.5" fill="#1E293B">• Coşkulu ve yiğitçe üslup (Halkta: Koçaklama)</text>\n  <text x="30" y="217" font-size="9.5" fill="#B91C1C">• Örnek: Vatan Destanı, Bir Yolcuya (Dur yolcu!)</text>\n\n  <rect x="360" y="150" width="322" height="94" rx="7" fill="#FFFBEB" stroke="#F59E0B" stroke-width="1.3"/>\n  <text x="521" y="167" text-anchor="middle" font-size="11" font-weight="bold" fill="#B45309">5. SATİRİK (ELEŞTİREL) ŞİİR</text>\n  <text x="372" y="185" font-size="9.5" fill="#1E293B">• Birey veya toplumun aksayan yönlerini eleştirir</text>\n  <text x="372" y="201" font-size="9.5" fill="#1E293B">• Divanda: Hiciv · Halkta: Taşlama · Modernde: Yergi</text>\n  <text x="372" y="217" font-size="9.5" fill="#B45309">• Örnek: Ruhsatî ("Yiğit belli değil, mert belli değil")</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
